-- Insert Quiz Questions for Lesson: Understand the Social Planner

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 16 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 16 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'understand-social-planner' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson understand-social-planner not found in module 16';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where is Social Planner found?', 
    '["CRM → Social Planner","Marketing → Social Planner","Settings → Social Planner","Automation → Social Planner"]'::jsonb,
    'Marketing → Social Planner',
    'Social Planner is found under Marketing → Social Planner in LeadProspectrr.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Do all connected platforms support the same post types and statistics?', 
    '["Yes, all platforms are identical","No, features and statistics vary by platform","Only Facebook and Instagram are supported","Yes, but only for paid accounts"]'::jsonb,
    'No, features and statistics vary by platform',
    'Features and statistics vary by platform. Each social network has different capabilities, post types, and available metrics.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is a sensible first weekly goal for this module?', 
    '["Ten posts per day","Three posts: Help, Proof, and Invitation","One post per month","Fifty posts per week"]'::jsonb,
    'Three posts: Help, Proof, and Invitation',
    'A sensible first weekly goal is three posts: one Help, one Proof, and one Invitation. This is manageable and builds a consistent routine.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
