-- Insert Quiz Questions for Lesson: Connect the Correct Social Account

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 16 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 16 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'connect-social-account' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson connect-social-account not found in module 16';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What permission is normally needed before LeadProspectrr can publish?', 
    '["Viewer permission","Admin or publishing permission","No permission is needed","Billing permission only"]'::jsonb,
    'Admin or publishing permission',
    'Admin or publishing permission is required for LeadProspectrr to publish posts on your behalf.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do if the correct business page does not appear?', 
    '["Select any page and fix it later","Check the platform login, role, ownership, and publishing permissions","Skip this platform and try another","Contact LeadProspectrr support immediately"]'::jsonb,
    'Check the platform login, role, ownership, and publishing permissions',
    'If the correct page does not appear, check your platform login, role, ownership, and publishing permissions before proceeding.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should the connected destination be recorded?', 
    '["It helps the business check ownership, access, and connection details later","It is required by LeadProspectrr terms of service","It automatically schedules posts","It increases post engagement"]'::jsonb,
    'It helps the business check ownership, access, and connection details later',
    'Recording the connected destination helps the business check ownership, access, and connection details later, especially when permissions expire or team members change.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
