</div>',
      title = 'Build One Useful Post',
      lesson_number = 3,
      sort_order = 3,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Build One Useful Post';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Build One Useful Post

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 16 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 16 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'build-useful-post' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson build-useful-post not found in module 16';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What are the three suggested post purposes?', 
    '["Help, Proof, and Invitation","Sell, Promote, and Advertise","Image, Video, and Text","Morning, Afternoon, and Evening"]'::jsonb,
    'Help, Proof, and Invitation',
    'The three suggested post purposes are Help (answer a question), Proof (share a result), and Invitation (offer a next step).', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How many main next actions should a simple post contain?', 
    '["One","Two","Three","As many as possible"]'::jsonb,
    'One',
    'A simple post should contain one main next action to avoid confusing the reader and make it clear what to do next.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'When should client results or images be used?', 
    '["Only with the right permission and after private information has been removed or approved","Whenever they are available","Only for paid clients","Never, they are not allowed"]'::jsonb,
    'Only with the right permission and after private information has been removed or approved',
    'Client results or images should only be used with the right permission and after private information has been removed or approved.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
